<?php
require_once __DIR__.'/includes/app.php';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$cart=$_SESSION['cart']??[];$a=(string)($_POST['action']??'');if($a==='add'){ $id=filter_var($_POST['product_id']??null,FILTER_VALIDATE_INT);$qty=filter_var($_POST['quantity']??1,FILTER_VALIDATE_INT);$st=db()->prepare('SELECT stock FROM products WHERE id=? AND is_active=1');$st->execute([$id]);$prod=$st->fetch();if(!$prod||!$qty||$qty<1){flash('Produit ou quantité invalide.','error');redirect('index.php');}$n=(int)($cart[$id]??0)+$qty;if($n>(int)$prod['stock']){flash('Stock insuffisant.','error');redirect('product.php?id='.$id);}$cart[$id]=$n;$_SESSION['cart']=$cart;flash('Produit ajouté au panier.');redirect('cart.php');}if($a==='update'){foreach(($_POST['quantities']??[])as$id=>$q){$id=filter_var($id,FILTER_VALIDATE_INT);$q=filter_var($q,FILTER_VALIDATE_INT);if(!$id)continue;if(!$q||$q<1){unset($cart[$id]);continue;}$st=db()->prepare('SELECT stock FROM products WHERE id=? AND is_active=1');$st->execute([$id]);$stock=$st->fetchColumn();if($stock===false)unset($cart[$id]);else$cart[$id]=min($q,(int)$stock);}$_SESSION['cart']=$cart;flash('Panier mis à jour.');redirect('cart.php');}if($a==='remove'){unset($cart[(int)($_POST['product_id']??0)]);$_SESSION['cart']=$cart;flash('Produit retiré.');redirect('cart.php');}}
$cart=$_SESSION['cart']??[];$items=[];$total=0;if($cart){$ids=array_values(array_map('intval',array_keys($cart)));$marks=implode(',',array_fill(0,count($ids),'?'));$st=db()->prepare("SELECT * FROM products WHERE is_active=1 AND id IN ({$marks})");$st->execute($ids);$items=$st->fetchAll();}foreach($items as &$i){$i['quantity']=min((int)($cart[$i['id']]??1),(int)$i['stock']);$i['line_total']=$i['price']*$i['quantity'];$total+=(float)$i['line_total'];}unset($i);render_header('Votre panier');?>
<section class="container section cart-page"><div class="section-heading"><div><span class="eyebrow">VOTRE SÉLECTION</span><h1>Votre panier</h1></div><a class="back-link" href="index.php#produits">← Continuer mes achats</a></div><?php if(!$items):?><div class="empty-state"><span>🛒</span><h2>Votre panier est vide</h2><p>Découvrez votre prochain coup de cœur.</p><a class="button button-primary" href="index.php#produits">Découvrir la boutique</a></div><?php else:?><div class="cart-layout"><form method="post" class="cart-items"><?=csrf_field()?><input type="hidden" name="action" value="update"><?php foreach($items as$i):?><article class="cart-item"><img src="<?=e(product_image($i['image']))?>" alt=""><div class="cart-item-info"><a href="product.php?id=<?=(int)$i['id']?>"><h3><?=e($i['name'])?></h3></a><span><?=money($i['price'])?></span></div><label class="quantity-label"><input type="number" name="quantities[<?=(int)$i['id']?>]" min="0" max="<?=(int)$i['stock']?>" value="<?=(int)$i['quantity']?>"></label><strong><?=money($i['line_total'])?></strong><button class="remove-button" type="submit" form="remove-<?=(int)$i['id']?>">×</button></article><?php endforeach?><button class="button button-outline">Mettre à jour</button></form><aside class="order-summary"><h2>Récapitulatif</h2><div class="summary-row"><span>Sous-total</span><strong><?=money($total)?></strong></div><div class="summary-row"><span>Livraison</span><span>À convenir</span></div><div class="summary-total"><span>Total estimé</span><strong><?=money($total)?></strong></div><p>Paiement à la livraison.</p><a class="button button-primary button-full" href="checkout.php">Passer la commande →</a></aside></div><?php foreach($items as$i):?><form id="remove-<?=(int)$i['id']?>" method="post" hidden><?=csrf_field()?><input type="hidden" name="action" value="remove"><input type="hidden" name="product_id" value="<?=(int)$i['id']?>"></form><?php endforeach;endif;?></section><?php render_footer();?>
